"use client"

import { Collapsible } from "@base-ui/react/collapsible"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { ChevronRight, Menu } from "@boxicons/react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"
import * as React from "react"

import { Button } from "./button"
import { Input } from "./input"
import { Separator } from "./separator"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "./sheet"
import { Skeleton } from "./skeleton"
import { useSketchOutline } from "./sketch-provider"
import { Tooltip, TooltipContent, TooltipTrigger } from "./tooltip"

const SIDEBAR_COOKIE = { NAME: "sidebar_state", MAX_AGE: 60 * 60 * 24 * 7 }
const SIDEBAR_WIDTH = { DEFAULT: "16rem", ICON: "3.5rem", MOBILE: "18rem" }
const SIDEBAR_GAP = "0.75rem"
const SIDEBAR_KEYBOARD_SHORTCUT = "b"
const MOBILE_BREAKPOINT = 768

function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState(false)

  React.useEffect(() => {
    const query = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => setIsMobile(query.matches)

    onChange()
    query.addEventListener("change", onChange)

    return () => query.removeEventListener("change", onChange)
  }, [])

  return isMobile
}

type SidebarContextProps = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)

  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobile] = React.useState(false)
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen)
  const open = openProp ?? uncontrolledOpen

  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value

      if (setOpenProp) {
        setOpenProp(openState)
      } else {
        setUncontrolledOpen(openState)
      }

      document.cookie = `${SIDEBAR_COOKIE.NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE.MAX_AGE}`
    },
    [setOpenProp, open]
  )

  const toggleSidebar = React.useCallback(() => {
    if (isMobile) {
      setOpenMobile((current) => !current)
      return
    }

    setOpen((current) => !current)
  }, [isMobile, setOpen])

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault()
        toggleSidebar()
      }
    }

    window.addEventListener("keydown", handleKeyDown)

    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [toggleSidebar])

  const state = open ? "expanded" : "collapsed"

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, toggleSidebar]
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <div
        data-slot="sidebar-wrapper"
        style={
          {
            "--sidebar-width": SIDEBAR_WIDTH.DEFAULT,
            "--sidebar-width-icon": SIDEBAR_WIDTH.ICON,
            "--sidebar-gap": SIDEBAR_GAP,
            ...style,
          } as React.CSSProperties
        }
        className={cn(
          "group/sidebar-wrapper flex min-h-svh w-full bg-background",
          className
        )}
        {...props}
      >
        {children}
      </div>
    </SidebarContext.Provider>
  )
}

function Sidebar({
  side = "left",
  collapsible = "offcanvas",
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right"
  collapsible?: "offcanvas" | "icon" | "none"
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()
  const panelOutline = useSketchOutline()

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile}>
        <SheetContent
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          side={side}
          showCloseButton={false}
          className="w-(--sidebar-width) gap-0 bg-sidebar p-0 text-sidebar-foreground"
          style={
            { "--sidebar-width": SIDEBAR_WIDTH.MOBILE } as React.CSSProperties
          }
          {...props}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
          </SheetHeader>
          <div className="flex h-full w-full flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    )
  }

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "group flex h-full w-(--sidebar-width) shrink-0 flex-col p-(--sidebar-gap) text-sidebar-foreground",
          className
        )}
        {...props}
      >
        <SidebarPanel outline={panelOutline} side={side}>
          {children}
        </SidebarPanel>
      </div>
    )
  }

  return (
    <div
      className="group peer hidden text-sidebar-foreground md:block"
      data-state={state}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-side={side}
      data-slot="sidebar"
    >
      <div
        data-slot="sidebar-gap"
        className={cn(
          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
          "group-data-[collapsible=offcanvas]:w-0",
          "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+var(--sidebar-gap)*2)]"
        )}
      />
      <div
        data-slot="sidebar-container"
        data-side={side}
        className={cn(
          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear data-[side=left]:left-0 data-[side=left]:group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)] data-[side=right]:right-0 data-[side=right]:group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)] md:flex",
          "p-(--sidebar-gap) group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+var(--sidebar-gap)*2)]",
          className
        )}
        {...props}
      >
        <SidebarPanel outline={panelOutline} side={side}>
          {children}
        </SidebarPanel>
      </div>
    </div>
  )
}

function SidebarPanel({
  children,
  outline,
  side,
}: {
  children: React.ReactNode
  outline: ReturnType<typeof useSketchOutline>
  side: "left" | "right"
}) {
  return (
    <div
      data-sidebar="sidebar"
      data-slot="sidebar-inner"
      data-side={side}
      className="relative isolate flex size-full flex-col rounded-xl bg-sidebar text-sidebar-foreground"
    >
      {children}
      <svg
        aria-hidden="true"
        data-sketch-outline
        ref={outline.ref}
        style={outline.style}
      />
    </div>
  )
}

function SidebarTrigger({
  className,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon-sm"
      className={className}
      onClick={(event) => {
        onClick?.(event)
        toggleSidebar()
      }}
      {...props}
    >
      <Menu />
      <span className="sr-only">Toggle Sidebar</span>
    </Button>
  )
}

function SidebarRail({ className, ...props }: React.ComponentProps<"button">) {
  const { toggleSidebar } = useSidebar()

  return (
    <button
      type="button"
      data-sidebar="rail"
      data-slot="sidebar-rail"
      aria-label="Toggle Sidebar"
      tabIndex={-1}
      onClick={toggleSidebar}
      title="Toggle Sidebar"
      className={cn(
        "group/rail absolute inset-y-0 z-20 hidden w-4 -translate-x-1/2 justify-center transition-all ease-linear group-data-[side=left]:-right-2 group-data-[side=right]:left-2 sm:flex",
        "in-data-[side=left]:cursor-w-resize in-data-[side=right]:cursor-e-resize",
        "[[data-side=left][data-state=collapsed]_&]:cursor-e-resize [[data-side=right][data-state=collapsed]_&]:cursor-w-resize",
        className
      )}
      {...props}
    >
      <Separator
        orientation="vertical"
        className="my-3 opacity-0 transition-opacity duration-200 ease-out motion-reduce:transition-none group-hover/rail:opacity-100 group-focus-visible/rail:opacity-100"
      />
    </button>
  )
}

function SidebarInset({ className, ...props }: React.ComponentProps<"main">) {
  return (
    <main
      data-slot="sidebar-inset"
      className={cn(
        "relative flex w-full flex-1 flex-col bg-background",
        className
      )}
      {...props}
    />
  )
}

function SidebarInput(props: React.ComponentProps<typeof Input>) {
  return <Input data-sidebar="input" {...props} />
}

function SidebarHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-header"
      data-sidebar="header"
      className={cn("flex flex-col gap-2 p-3 group-data-[collapsible=icon]:p-2", className)}
      {...props}
    />
  )
}

function SidebarFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-footer"
      data-sidebar="footer"
      className={cn("mt-auto flex flex-col gap-2 p-3 group-data-[collapsible=icon]:p-2", className)}
      {...props}
    />
  )
}

function SidebarSeparator({
  className,
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-sidebar="separator"
      className={cn("mx-3 w-auto", className)}
      {...props}
    />
  )
}

function SidebarContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-content"
      data-sidebar="content"
      className={cn(
        "flex min-h-0 flex-1 flex-col gap-1 overflow-auto group-data-[collapsible=icon]:overflow-hidden",
        className
      )}
      {...props}
    />
  )
}

const SIDEBAR_GROUP_CLASS =
	"relative flex w-full min-w-0 flex-col p-2"

const SIDEBAR_GROUP_LABEL_CLASS =
  "flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-sidebar-foreground/70 text-xs transition-[margin,opacity] duration-200 ease-linear outline-hidden group-data-[collapsible=icon]:-mt-8 group-data-[collapsible=icon]:opacity-0 [&>svg]:size-4 [&>svg]:shrink-0"

/*
  Sidebar parts keep their semantic tag (<li>, <ul>, and a <div> label) while
  Base UI types every collapsible part against <div> or <button>. The casts at
  each Collapsible boundary forward props untouched; only the element differs.
*/
const COLLAPSIBLE_PANEL_CLASS =
  "h-(--collapsible-panel-height) overflow-hidden transition-[height,opacity] duration-200 ease-out motion-reduce:transition-none data-ending-style:h-0 data-ending-style:opacity-0 data-starting-style:h-0 data-starting-style:opacity-0"

const CollapsibleGroupContext = React.createContext(false)

const CollapsibleMenuItemContext = React.createContext(false)

type SidebarGroupProps = React.ComponentProps<"div"> & {
  collapsible?: boolean
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

function SidebarGroup({
  className,
  collapsible = false,
  defaultOpen = true,
  onOpenChange,
  open,
  ...props
}: SidebarGroupProps) {
  if (!collapsible) {
    return (
      <div
        data-slot="sidebar-group"
        data-sidebar="group"
        className={cn(SIDEBAR_GROUP_CLASS, className)}
        {...props}
      />
    )
  }

  return (
    <CollapsibleGroupContext.Provider value={true}>
      <Collapsible.Root
        data-slot="sidebar-group"
        data-sidebar="group"
        defaultOpen={defaultOpen}
        open={open}
        onOpenChange={onOpenChange}
        className={cn(
          "group/collapsible",
          SIDEBAR_GROUP_CLASS,
          "mt-1",
          className
        )}
        {...props}
      />
    </CollapsibleGroupContext.Provider>
  )
}

function SidebarGroupLabel(
  props: useRender.ComponentProps<"div"> & React.ComponentProps<"div">
) {
  const isCollapsible = React.useContext(CollapsibleGroupContext)

  if (isCollapsible) {
    return <CollapsibleGroupLabel {...props} />
  }

  return <StaticGroupLabel {...props} />
}

function StaticGroupLabel({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div"> & React.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      { className: cn(SIDEBAR_GROUP_LABEL_CLASS, className) },
      props
    ),
    render,
    state: {
      slot: "sidebar-group-label",
      sidebar: "group-label",
    },
  })
}

function CollapsibleGroupLabel({
  children,
  className,
  render,
  ...props
}: useRender.ComponentProps<"div"> & React.ComponentProps<"div">) {
  const triggerProps = { ...props, render } as Collapsible.Trigger.Props

  return (
    <Collapsible.Trigger
      data-slot="sidebar-group-label"
      data-sidebar="group-label"
      className={cn(
        SIDEBAR_GROUP_LABEL_CLASS,
        "w-full cursor-pointer select-none hover:text-sidebar-foreground",
        className
      )}
      {...triggerProps}
    >
      {children}
      <ChevronRight className="ml-auto size-3.5 transition-transform duration-200 ease-out motion-reduce:transition-none group-data-open/collapsible:rotate-90" />
    </Collapsible.Trigger>
  )
}

function SidebarGroupAction({
  className,
  render,
  ...props
}: useRender.ComponentProps<"button"> & React.ComponentProps<"button">) {
  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn(
          "absolute top-3.5 right-3 flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-hidden transition-transform group-data-[collapsible=icon]:hidden after:absolute after:-inset-2 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground md:after:hidden [&>svg]:size-4 [&>svg]:shrink-0",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-group-action",
      sidebar: "group-action",
    },
  })
}

function SidebarGroupContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  const isCollapsible = React.useContext(CollapsibleGroupContext)

  if (isCollapsible) {
    return (
      <Collapsible.Panel
        data-slot="sidebar-group-content"
        data-sidebar="group-content"
        className={cn(
          COLLAPSIBLE_PANEL_CLASS,
          "w-full pt-1.5 text-sm",
          className
        )}
        {...props}
      />
    )
  }

  return (
    <div
      data-slot="sidebar-group-content"
      data-sidebar="group-content"
      className={cn("w-full text-sm", className)}
      {...props}
    />
  )
}

function SidebarMenu({ className, ...props }: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="sidebar-menu"
      data-sidebar="menu"
      className={cn("flex w-full min-w-0 flex-col gap-0.5", className)}
      {...props}
    />
  )
}

const SIDEBAR_MENU_ITEM_CLASS = "group/menu-item relative"

type SidebarMenuItemProps = React.ComponentProps<"li"> & {
  collapsible?: boolean
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

function SidebarMenuItem({
  className,
  collapsible = false,
  defaultOpen = true,
  onOpenChange,
  open,
  ...props
}: SidebarMenuItemProps) {
  if (!collapsible) {
    return (
      <li
        data-slot="sidebar-menu-item"
        data-sidebar="menu-item"
        className={cn(SIDEBAR_MENU_ITEM_CLASS, className)}
        {...props}
      />
    )
  }

  return (
    <CollapsibleMenuItemContext.Provider value={true}>
      <Collapsible.Root
        data-slot="sidebar-menu-item"
        data-sidebar="menu-item"
        defaultOpen={defaultOpen}
        open={open}
        onOpenChange={onOpenChange}
        render={<li />}
        className={cn(
          "group/collapsible-item",
          SIDEBAR_MENU_ITEM_CLASS,
          className
        )}
        {...(props as Collapsible.Root.Props)}
      />
    </CollapsibleMenuItemContext.Provider>
  )
}

const sidebarMenuButtonVariants = cva(
  "peer/menu-button group/menu-button relative isolate flex w-full items-center gap-2 overflow-clip [overflow-clip-margin:6px] rounded-lg p-2 text-left text-sm outline-hidden transition-[width,height,padding,background-color] group-has-data-[sidebar=menu-action]/menu-item:pr-8 group-data-[collapsible=icon]:size-10! group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-2! group-data-[collapsible=icon]:[&>span]:hidden hover:bg-sidebar-accent hover:text-sidebar-accent-foreground active:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 data-active:font-medium data-active:text-sidebar-accent-foreground [&>span]:truncate [&_svg]:size-5 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "",
        outline: "bg-background",
      },
      size: {
        default: "h-9 text-sm",
        sm: "h-8 text-xs",
        lg: "h-12 text-sm group-data-[collapsible=icon]:p-0!",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function SidebarMenuButton({
  render,
  isActive = false,
  variant = "default",
  size = "default",
  tooltip,
  className,
  children,
  ...props
}: useRender.ComponentProps<"button"> &
  React.ComponentProps<"button"> & {
    isActive?: boolean
    tooltip?: string | React.ComponentProps<typeof TooltipContent>
  } & VariantProps<typeof sidebarMenuButtonVariants>) {
  const { isMobile, state } = useSidebar()
  const isCollapsibleItem = React.useContext(CollapsibleMenuItemContext)
  const sketchOutline = useSketchOutline()
  const hasOutline = isActive || variant === "outline"

  const comp = useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        children: (
          <>
            {children}
            {isCollapsibleItem && (
              <ChevronRight className="ml-auto size-3.5 transition-transform duration-200 ease-out motion-reduce:transition-none group-data-open/collapsible-item:rotate-90 group-data-[collapsible=icon]:hidden" />
            )}
            {hasOutline && (
              <svg
                aria-hidden="true"
                data-sketch-outline
                ref={sketchOutline.ref}
                style={sketchOutline.style}
              />
            )}
          </>
        ),
        className: cn(
          sidebarMenuButtonVariants({ variant, size }),
          hasOutline && "text-sidebar-accent-foreground",
          className
        ),
      },
      props
    ),
    render: getMenuButtonRender({ isCollapsibleItem, render, tooltip }),
    state: {
      slot: "sidebar-menu-button",
      sidebar: "menu-button",
      size,
      active: isActive,
    },
  })

  if (!tooltip) {
    return comp
  }

  const tooltipProps = typeof tooltip === "string" ? { children: tooltip } : tooltip

  return (
    <Tooltip>
      {comp}
      <TooltipContent
        side="right"
        align="center"
        hidden={state !== "collapsed" || isMobile}
        {...tooltipProps}
      />
    </Tooltip>
  )
}

function getMenuButtonRender({
  isCollapsibleItem,
  render,
  tooltip,
}: {
  isCollapsibleItem: boolean
  render: useRender.ComponentProps<"button">["render"]
  tooltip: unknown
}) {
  const collapsibleRender = isCollapsibleItem ? (
    <Collapsible.Trigger render={render as Collapsible.Trigger.Props["render"]} />
  ) : (
    render
  )

  if (!tooltip) {
    return collapsibleRender
  }

  return <TooltipTrigger render={collapsibleRender} />
}

function SidebarMenuAction({
  className,
  render,
  showOnHover = false,
  ...props
}: useRender.ComponentProps<"button"> &
  React.ComponentProps<"button"> & {
    showOnHover?: boolean
  }) {
  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn(
          "absolute top-1.5 right-1 flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-hidden transition-transform group-data-[collapsible=icon]:hidden peer-hover/menu-button:text-sidebar-accent-foreground peer-data-[size=lg]/menu-button:top-2.5 peer-data-[size=sm]/menu-button:top-1 after:absolute after:-inset-2 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground md:after:hidden [&>svg]:size-4 [&>svg]:shrink-0",
          showOnHover &&
            "group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 peer-data-active/menu-button:text-sidebar-accent-foreground aria-expanded:opacity-100 md:opacity-0",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-menu-action",
      sidebar: "menu-action",
    },
  })
}

function SidebarMenuBadge({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-menu-badge"
      data-sidebar="menu-badge"
      className={cn(
        "pointer-events-none absolute right-2 flex h-5 min-w-5 items-center justify-center rounded-md px-1 text-sidebar-foreground text-xs tabular-nums select-none group-data-[collapsible=icon]:hidden peer-hover/menu-button:text-sidebar-accent-foreground peer-data-[size=default]/menu-button:top-1.5 peer-data-[size=lg]/menu-button:top-3.5 peer-data-[size=sm]/menu-button:top-1",
        className
      )}
      {...props}
    />
  )
}

function SidebarMenuSkeleton({
  className,
  showIcon = false,
  ...props
}: React.ComponentProps<"div"> & {
  showIcon?: boolean
}) {
  const [width] = React.useState(() => `${Math.floor(Math.random() * 40) + 50}%`)

  return (
    <div
      data-slot="sidebar-menu-skeleton"
      data-sidebar="menu-skeleton"
      className={cn("flex h-8 items-center gap-2 rounded-md px-2", className)}
      {...props}
    >
      {showIcon && (
        <Skeleton className="size-4 rounded-md" data-sidebar="menu-skeleton-icon" />
      )}
      <Skeleton
        className="h-4 max-w-(--skeleton-width) flex-1"
        data-sidebar="menu-skeleton-text"
        style={{ "--skeleton-width": width } as React.CSSProperties}
      />
    </div>
  )
}

const SIDEBAR_MENU_SUB_CLASS =
  "relative mx-3.5 flex min-w-0 flex-col gap-1 py-0.5 pl-3 group-data-[collapsible=icon]:hidden"

function SidebarMenuSub({
  children,
  className,
  ...props
}: React.ComponentProps<"ul">) {
  const isCollapsibleItem = React.useContext(CollapsibleMenuItemContext)

  if (isCollapsibleItem) {
    return (
      <Collapsible.Panel
        data-slot="sidebar-menu-sub"
        data-sidebar="menu-sub"
        render={<ul />}
